package io.tornado.notification;
import io.tornado.persistence.*;import org.junit.jupiter.api.Test;import org.springframework.test.util.ReflectionTestUtils;import java.math.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class TelegramMessageFormatterTest{@Test void rendersAllLevelsAndEveryPersistedTouch(){Coin c=new Coin("BTC","BTCUSDT");ReflectionTestUtils.setField(c,"id",1L);BestMethodMix m=new BestMethodMix(c,900,3,1,List.of("A","B","C"),List.of(1,1,1),List.of("A","B","C"),100,60,70,.5);MixTradeSimulation s=new MixTradeSimulation(c,m,Direction.UP,3,new BigDecimal("100"),TpSlLevels.defaults(),Instant.EPOCH);ReflectionTestUtils.setField(s,"id",9L);TelegramMessageFormatter f=new TelegramMessageFormatter();assertThat(f.open(s)).contains("TORNIDO MIX SIGNAL","TP1","TP2","TP3","SL1","SL2","SL3","Selected historical hit metric");var e=s.observeMilestones(new BigDecimal("100.6"),Instant.EPOCH.plusSeconds(2));assertThat(f.update(s,e.milestones())).contains("TP1 TOUCHED","TP2 TOUCHED","✅ 1️⃣ TP1","✅ 2️⃣ TP2","⬜ 3️⃣ TP3","Status: ⏳ OPEN");}@Test void labelsHistoricalRateWithRepresentativeRankingTp(){Coin c=new Coin("BTC","BTCUSDT");ReflectionTestUtils.setField(c,"id",1L);BestMethodMix m=new BestMethodMix(c,900,3,1,List.of("A","B","C"),List.of(1,1,1),List.of("A","B","C"),100,60,70,.5,2,new BigDecimal(".50"));MixTradeSimulation s=new MixTradeSimulation(c,m,Direction.UP,3,new BigDecimal("100"),TpSlLevels.defaults(),Instant.EPOCH);assertThat(new TelegramMessageFormatter().open(s)).contains("Selected historical hit metric: TP2 (+0.5%)","Historical TP2 (+0.5%) Hit Rate");}}
